**Opt-In Platform Backend (serve_web.py) - Core Endpoints**
```python
from flask import Flask, request, jsonify
import json
import time
import os
from datetime import datetime

app = Flask(__name__)
REQUEST_FILE = 'optin_requests.json'
RATE_LIMIT_WINDOW = 3600  # 1 hour
RATE_LIMIT_COUNT = 5

@app.route('/submit-request', methods=['POST'])
def submit_request():
    # Validate required fields and mandatory consent
    data = request.json
    required = ['name', 'email', 'request_type', 'description']

    for field in required:
        if not data.get(field):
            return jsonify({'error': f'Missing required field: {field}'}), 400

    if data.get('consent') != True:
        return jsonify({'error': 'Consent must be explicitly set to true'}), 400

    # Rate limiting logic
    ip = request.remote_addr
    current_time = time.time()
    # ... rate limiting implementation ...

    # Save request
    request_data = {
        **data,
        'timestamp': datetime.utcnow().isoformat(),
        'ip_address': ip
    }

    # File locking for safe concurrent writes
    with open(REQUEST_FILE, 'a') as f:
        f.write(json.dumps(request_data) + '\n')

    return jsonify({'status': 'success', 'message': 'Request submitted'})

@app.route('/optin-stats', methods=['GET'])
def get_optin_stats():
    if os.path.exists(REQUEST_FILE):
        with open(REQUEST_FILE, 'r') as f:
            lines = f.readlines()
        return jsonify({
            'total_requests': len(lines),
            'requests': [json.loads(line) for line in lines[-10:]]  # Last 10
        })
    return jsonify({'total_requests': 0, 'requests': []})
```

